/**
 * Core vendor repository contract.
 *
 * Part A declares lookup, listing, and aggregate persistence
 * operations.
 *
 * Nested entity operations will be added in later parts.
 */
export interface VendorRepository {
  /**
   * Creates a complete vendor aggregate.
   */
  create(
    input: CreateVendorRepositoryInput
  ): Promise<VendorAggregate>;

  /**
   * Returns a complete vendor using its internal ID.
   */
  findById(
    vendorId: string
  ): Promise<VendorAggregate | null>;

  /**
   * Returns a vendor using its public vendor code.
   */
  findByVendorCode(
    vendorCode: string
  ): Promise<VendorAggregate | null>;

  /**
   * Returns a vendor using its registered email.
   */
  findByEmail(
    email: string
  ): Promise<VendorAggregate | null>;

  /**
   * Returns a vendor using its registered phone number.
   */
  findByPhone(
    phone: string
  ): Promise<VendorAggregate | null>;

  /**
   * Returns a paginated vendor list.
   */
  findMany(
    query?: VendorRepositoryListQuery
  ): Promise<
    VendorRepositoryPage<VendorAggregate>
  >;

  /**
   * Returns lightweight vendor summaries.
   */
  findSummaries(
    query?: VendorRepositoryListQuery
  ): Promise<
    VendorRepositoryPage<
      VendorAggregateSummary
    >
  >;

  /**
   * Updates top-level vendor information.
   */
  update(
    vendorId: string,
    input: UpdateVendorRepositoryInput
  ): Promise<VendorAggregate | null>;

  /**
   * Deletes a vendor and its owned domain records.
   *
   * The eventual implementation may use soft deletion
   * instead of physical deletion.
   */
  delete(
    vendorId: string
  ): Promise<VendorRepositoryDeleteResult>;

  /**
   * Determines whether a vendor exists.
   */
  exists(
    vendorId: string
  ): Promise<boolean>;

  /**
   * Checks fields that must remain unique.
   */
  checkUniqueness(
    query: VendorRepositoryUniquenessQuery
  ): Promise<VendorRepositoryUniquenessResult>;

  /**
   * Returns vendor dashboard statistics.
   */
  getStatistics():
    Promise<VendorRepositoryStatistics>;
}

/**
 * Repository transaction context.
 *
 * A concrete Prisma implementation can later provide the
 * Prisma transaction client through this abstraction without
 * exposing Prisma to the service layer.
 */
export interface VendorRepositoryTransaction {
  repository: VendorRepository;
}

/**
 * Function executed inside a repository transaction.
 */
export type VendorRepositoryTransactionCallback<T> =
  (
    transaction:
      VendorRepositoryTransaction
  ) => Promise<T>;

/**
 * Repository transaction manager contract.
 */
export interface VendorRepositoryTransactionManager {
  runInTransaction<T>(
    callback:
      VendorRepositoryTransactionCallback<T>
  ): Promise<T>;
}

/**
 * Default repository pagination values.
 */
export const DEFAULT_VENDOR_REPOSITORY_PAGE =
  1;

export const DEFAULT_VENDOR_REPOSITORY_PAGE_SIZE =
  20;

export const MAX_VENDOR_REPOSITORY_PAGE_SIZE =
  100;

/**
 * Default vendor sorting configuration.
 */
export const DEFAULT_VENDOR_REPOSITORY_SORT:
  VendorRepositorySort = {
    field: "createdAt",
    direction: "desc",
  };

/**
 * Creates normalized pagination metadata.
 */
export function createVendorPaginationMetadata(
  page: number,
  pageSize: number,
  totalRecords: number
): VendorRepositoryPaginationMetadata {
  const safePage =
    Number.isInteger(page) &&
    page > 0
      ? page
      : DEFAULT_VENDOR_REPOSITORY_PAGE;

  const safePageSize =
    Number.isInteger(pageSize) &&
    pageSize > 0
      ? Math.min(
          pageSize,
          MAX_VENDOR_REPOSITORY_PAGE_SIZE
        )
      : DEFAULT_VENDOR_REPOSITORY_PAGE_SIZE;

  const safeTotalRecords =
    Number.isFinite(totalRecords) &&
    totalRecords > 0
      ? Math.floor(totalRecords)
      : 0;

  const totalPages =
    safeTotalRecords === 0
      ? 0
      : Math.ceil(
          safeTotalRecords /
            safePageSize
        );

  return {
    page: safePage,

    pageSize: safePageSize,

    totalRecords:
      safeTotalRecords,

    totalPages,

    hasNextPage:
      totalPages > 0 &&
      safePage < totalPages,

    hasPreviousPage:
      totalPages > 0 &&
      safePage > 1,
  };
}

/**
 * Creates an empty repository page.
 */
export function createEmptyVendorRepositoryPage<T>(
  pagination?:
    Partial<VendorRepositoryPagination>
): VendorRepositoryPage<T> {
  const page =
    pagination?.page ??
    DEFAULT_VENDOR_REPOSITORY_PAGE;

  const pageSize =
    pagination?.pageSize ??
    DEFAULT_VENDOR_REPOSITORY_PAGE_SIZE;

  return {
    items: [],

    pagination:
      createVendorPaginationMetadata(
        page,
        pageSize,
        0
      ),
  };
}

/**
 * Calculates the database offset for paginated queries.
 */
export function calculateVendorRepositoryOffset(
  pagination?:
    VendorRepositoryPagination
): number {
  const page =
    pagination?.page &&
    pagination.page > 0
      ? pagination.page
      : DEFAULT_VENDOR_REPOSITORY_PAGE;

  const pageSize =
    pagination?.pageSize &&
    pagination.pageSize > 0
      ? Math.min(
          pagination.pageSize,
          MAX_VENDOR_REPOSITORY_PAGE_SIZE
        )
      : DEFAULT_VENDOR_REPOSITORY_PAGE_SIZE;

  return (page - 1) * pageSize;
}

/**
 * Returns a normalized page size.
 */
export function normalizeVendorRepositoryPageSize(
  pageSize?: number
): number {
  if (
    pageSize === undefined ||
    !Number.isInteger(pageSize) ||
    pageSize <= 0
  ) {
    return DEFAULT_VENDOR_REPOSITORY_PAGE_SIZE;
  }

  return Math.min(
    pageSize,
    MAX_VENDOR_REPOSITORY_PAGE_SIZE
  );
}

/**
 * Determines whether any repository filter is present.
 */
export function hasVendorRepositoryFilters(
  filter?:
    VendorRepositoryFilter
): boolean {
  if (!filter) {
    return false;
  }

  return Object.values(filter).some(
    (value) =>
      value !== undefined &&
      value !== null &&
      value !== ""
  );
}

