/**
 * Creates defensive copies of service-area repository input.
 */
export function cloneCreateVendorServiceAreaRepositoryInput(
  input:
    CreateVendorServiceAreaRepositoryInput
): CreateVendorServiceAreaRepositoryInput {
  return {
    ...input,

    serviceablePostalCodes:
      input.serviceablePostalCodes
        ? [
            ...input
              .serviceablePostalCodes,
          ]
        : input.serviceablePostalCodes,

    createdAt:
      input.createdAt
        ? new Date(
            input.createdAt.getTime()
          )
        : undefined,

    updatedAt:
      input.updatedAt
        ? new Date(
            input.updatedAt.getTime()
          )
        : undefined,
  };
}

