/**
 * Standard vendor repository error codes.
 */
export type VendorRepositoryErrorCode =
  | "VENDOR_NOT_FOUND"
  | "SERVICE_AREA_NOT_FOUND"
  | "SERVICE_NOT_FOUND"
  | "PRICING_NOT_FOUND"
  | "VEHICLE_NOT_FOUND"
  | "DOCUMENT_NOT_FOUND"
  | "BANK_DETAILS_NOT_FOUND"
  | "DUPLICATE_VENDOR"
  | "DUPLICATE_EMAIL"
  | "DUPLICATE_PHONE"
  | "DUPLICATE_GST_NUMBER"
  | "DUPLICATE_PAN_NUMBER"
  | "DUPLICATE_REGISTRATION_NUMBER"
  | "DUPLICATE_BANK_ACCOUNT"
  | "DUPLICATE_UPI_ID"
  | "INVALID_REPOSITORY_INPUT"
  | "TRANSACTION_FAILED"
  | "DATABASE_ERROR"
  | "UNKNOWN_REPOSITORY_ERROR";

/**
 * Serializable repository error details.
 */
export interface VendorRepositoryErrorDetails {
  field?: string;

  value?: unknown;

  vendorId?: string;

  entityId?: string;

  cause?: unknown;
}

/**
 * Vendor repository error.
 */
export class VendorRepositoryError
  extends Error {
  readonly code:
    VendorRepositoryErrorCode;

  readonly details?:
    VendorRepositoryErrorDetails;

  constructor(
    code:
      VendorRepositoryErrorCode,
    message: string,
    details?:
      VendorRepositoryErrorDetails
  ) {
    super(message);

    this.name =
      "VendorRepositoryError";

    this.code = code;

    this.details = details;

    Object.setPrototypeOf(
      this,
      VendorRepositoryError.prototype
    );
  }
}

/**
 * Determines whether an error is a vendor repository error.
 */
export function isVendorRepositoryError(
  error: unknown
): error is VendorRepositoryError {
  return (
    error instanceof
    VendorRepositoryError
  );
}

/**
 * Creates a vendor-not-found repository error.
 */
export function createVendorNotFoundRepositoryError(
  vendorId: string
): VendorRepositoryError {
  return new VendorRepositoryError(
    "VENDOR_NOT_FOUND",
    "Vendor was not found.",
    {
      vendorId,
    }
  );
}

/**
 * Creates a database repository error.
 */
export function createVendorDatabaseRepositoryError(
  message: string,
  cause?: unknown
): VendorRepositoryError {
  return new VendorRepositoryError(
    "DATABASE_ERROR",
    message,
    {
      cause,
    }
  );
}

